application.css:
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #f4f7fb;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.5;
}

body {
  margin: 0;
}

.page-shell {
  width: min(100% - 2rem, 760px);
  margin: 0 auto;
  padding: 2.5rem 0 4rem;
}

.quiz-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .35rem;
  color: #315ca8;
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .6rem;
  font-size: clamp(2rem, 6vw, 3rem);
  line-height: 1.1;
}

.question-card,
.result-panel {
  border: 1px solid #c9d4e5;
  border-radius: .75rem;
  background: #fff;
  box-shadow: 0 3px 12px rgb(23 32 51 / 7%);
}

.question-card {
  margin: 0 0 1.25rem;
  padding: 1.25rem;
}

legend {
  max-width: 100%;
  padding: 0 .35rem;
  font-weight: 700;
}

.options {
  display: grid;
  gap: .7rem;
  margin-top: .75rem;
}

.option {
  display: flex;
  align-items: center;
  gap: .7rem;
  min-height: 2.75rem;
  padding: .65rem .8rem;
  border: 2px solid #d9e1ed;
  border-radius: .5rem;
  cursor: pointer;
}

.option:hover {
  border-color: #6a8dcc;
  background: #f5f8ff;
}

.option:has(input:checked) {
  border-color: #315ca8;
  background: #edf3ff;
}

input[type="radio"] {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: #315ca8;
}

button {
  border: 0;
  border-radius: .5rem;
  cursor: pointer;
  font: inherit;
  font-weight: 700;
}

.submit-button {
  padding: .8rem 1.4rem;
  color: #fff;
  background: #234985;
}

.submit-button:hover {
  background: #183866;
}

.form-message {
  margin-bottom: 1rem;
  padding: .75rem 1rem;
  border-left: 4px solid #a52a2a;
  color: #7a1e1e;
  background: #fff0f0;
}

.result-panel {
  margin-top: 1.5rem;
  padding: 1.25rem;
}

.result-panel h2 {
  margin-bottom: .35rem;
  font-size: 1.2rem;
}

.result-panel p {
  margin-bottom: 0;
}

[hidden] {
  display: none !important;
}

:focus-visible {
  outline: 3px solid #e19a16;
  outline-offset: 3px;
}

@media (max-width: 480px) {
  .page-shell {
    width: min(100% - 1.25rem, 760px);
    padding-top: 1.5rem;
  }
}

application.javascript:
const form = document.querySelector('#quiz-form');
const formError = document.querySelector('#form-error');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const scoreNumber = document.querySelector('#score-number');

const correctAnswers = Object.freeze({
  'question-1': 'mars',
  'question-2': 'pacific',
  'question-3': 'html'
});

function getSelectedAnswer(questionName) {
  const selected = form.querySelector(`input[name="${questionName}"]:checked`);
  return selected ? selected.value : null;
}

function getAnswers() {
  return Object.keys(correctAnswers).map((questionName) => ({
    questionName,
    answer: getSelectedAnswer(questionName)
  }));
}

function showValidationError() {
  formError.textContent = 'Please select one answer for each question before submitting.';
  formError.hidden = false;
  const first unanswered = Object.keys(correctAnswers).find((name) => !getSelectedAnswer(name));
  const firstInput = form.querySelector(`input[name="${firstUnanswered}"]`);
  if (firstInput) firstInput.focus();
}

function calculateScore(answers) {
  return answers.reduce((score, item) => (
    score + (item.answer === correctAnswers[item.questionName] ? 1 : 0)
  ), 0);
}

function displayScore(score) {
  scoreNumber.textContent = String(score);
  scoreElement.dataset.score = String(score);
  scoreElement.hidden = false;
}

function handleSubmit(event) {
  event.preventDefault();
  const answers = getAnswers();
  const complete = answers.every((item) => item.answer !== null);

  if (!complete) {
    showValidationError();
    return;
  }

  formError.hidden = true;
  displayScore(calculateScore(answers));
}

form.addEventListener('submit', handleSubmit);
